from typing import Literal

Regime = Literal["strictly log-convex", "log-linear", "strictly log-concave"]

def classify(alpha: int, beta: int, gamma: int, delta: int) -> Regime:
    """Classify log-behavior of (alpha*n+beta)a(n+1)=(gamma*n+delta)a(n)."""
    disc: int = gamma * beta - alpha * delta
    if disc > 0:
        return "strictly log-convex"
    if disc == 0:
        return "log-linear"
    return "strictly log-concave"

