function CURVATURE_WITNESS(a0, alpha, beta, gamma, delta, m):
    a[0] <- a0
    for n in 0 .. m:
        a[n+1] <- a[n] * (gamma*n + delta) / (alpha*n + beta)
    Delta <- gamma*beta - alpha*delta
    for n in 0 .. m-1:
        D <- a[n]*a[n+2] - a[n+1]^2
        assert sign(D) == sign(Delta)
    return [sign(a[n]*a[n+2] - a[n+1]^2) for n in 0 .. m-1]

function INFER(ratio):
    r0, r1, r2 <- ratio(0), ratio(1), ratio(2)
    if r0 == r1 == r2:            # geometric
        return clear(0, 1, 0, r0)
    for n in {0,1,2}:            # row for (alpha,beta,gamma,delta)
        row[n] <- [-r(n)*n, -r(n), n, 1]
    for j in {0,1,2,3}:          # signed cofactor minors
        v[j] <- (-1)^j * det3(rows without column j)
    return clear(v)              # scale to smallest integers

