from fractions import Fraction
from math import gcd
from typing import Callable, List, Tuple

def _det3(m: List[List[Fraction]]) -> Fraction:
    return (m[0][0]*(m[1][1]*m[2][2]-m[1][2]*m[2][1])
            - m[0][1]*(m[1][0]*m[2][2]-m[1][2]*m[2][0])
            + m[0][2]*(m[1][0]*m[2][1]-m[1][1]*m[2][0]))

def _clear(vals: List[Fraction]) -> Tuple[int, int, int, int]:
    lcm = 1
    for v in vals:
        lcm = lcm * v.denominator // gcd(lcm, v.denominator)
    ints = [int(v * lcm) for v in vals]
    g = 0
    for x in ints:
        g = gcd(g, abs(x))
    if g:
        ints = [x // g for x in ints]
    if ints[1] < 0 or (ints[1] == 0 and ints[0] < 0):
        ints = [-x for x in ints]
    return (ints[0], ints[1], ints[2], ints[3])

def infer(ratio: Callable[[int], Fraction]) -> Tuple[int, int, int, int]:
    """Recover integer (alpha,beta,gamma,delta) from a linear/linear term ratio."""
    r0, r1, r2 = ratio(0), ratio(1), ratio(2)
    if r0 == r1 == r2:
        return _clear([Fraction(0), Fraction(1), Fraction(0), r0])
    rows = [[-ratio(n)*n, -ratio(n), Fraction(n), Fraction(1)] for n in (0, 1, 2)]
    cols = [0, 1, 2, 3]
    null = [(-1)**j * _det3([[row[c] for c in cols if c != j] for row in rows])
            for j in cols]
    return _clear(null)
